import React, { useState, useRef, useEffect, useCallback, memo } from 'react';
import { Flow } from 'flow-sdk';
import { Icon } from './components/Icon';
import { Sidebar } from './components/Sidebar';
import { Stage } from './components/Stage';
import { Timeline } from './components/Timeline';
import { TextConfig, MediaAsset, GOOGLE_FONTS_URL } from './types';
import { renderVideo } from './services/renderer';

import { timeController } from './services/TimeController';

const MemoizedSidebar = memo(Sidebar);

// ── Runtime injection of fonts + global CSS (index.html is ignored in Flow sandbox) ──
const INJECTED_STYLE_ID = 'typeoverlays-global-styles';
const INJECTED_FONT_ID = 'typeoverlays-material-symbols';
const INJECTED_BODY_FONT_ID = 'typeoverlays-google-sans';

function useGlobalStyles() {
    useEffect(() => {
        const preconnect1 = document.createElement('link');
        preconnect1.rel = 'preconnect';
        preconnect1.href = 'https://fonts.googleapis.com';
        document.head.appendChild(preconnect1);

        const preconnect2 = document.createElement('link');
        preconnect2.rel = 'preconnect';
        preconnect2.href = 'https://fonts.gstatic.com';
        preconnect2.crossOrigin = 'anonymous';
        document.head.appendChild(preconnect2);

        if (!document.getElementById(INJECTED_FONT_ID)) {
            const fontLink = document.createElement('link');
            fontLink.id = INJECTED_FONT_ID;
            fontLink.rel = 'stylesheet';
            fontLink.href = 'https://fonts.googleapis.com/css2?family=Material+Symbols+Rounded:opsz,wght,FILL,GRAD@20..48,100..700,0..1,-50..200&display=swap';
            document.head.appendChild(fontLink);
        }

        if (!document.getElementById(INJECTED_BODY_FONT_ID)) {
            const bodyFont = document.createElement('link');
            bodyFont.id = INJECTED_BODY_FONT_ID;
            bodyFont.rel = 'stylesheet';
            bodyFont.href = 'https://fonts.googleapis.com/css2?family=Google+Sans:wght@400;500;600;700&family=Google+Sans+Flex:wght@400;500;600;700&family=Google+Sans+Text:wght@400;500;600;700&display=swap';
            document.head.appendChild(bodyFont);
        }

        // Load text layer fonts (Instrument Sans, Baskervville, etc.)
        const textFontLink = document.createElement('link');
        textFontLink.rel = 'stylesheet';
        textFontLink.crossOrigin = 'anonymous';
        textFontLink.href = GOOGLE_FONTS_URL;
        document.head.appendChild(textFontLink);

        if (!document.getElementById(INJECTED_STYLE_ID)) {
            const style = document.createElement('style');
            style.id = INJECTED_STYLE_ID;
            style.textContent = `\n                * { box-sizing: border-box; }\n                .material-symbols-rounded { font-variation-settings: 'FILL' 0, 'wght' 300, 'GRAD' 0, 'opsz' 20; }\n                .no-scrollbar::-webkit-scrollbar { display: none; }\n                .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }\n\n                input[type=range] { -webkit-appearance: none; appearance: none; background: transparent; width: 100%; }\n                input[type=range]::-webkit-slider-runnable-track { width: 100%; height: 3px; background: #595959; border-radius: 9999px; }\n                input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; appearance: none; width: 10px; height: 10px; border-radius: 50%; background: white; box-shadow: 0px 1px 3px rgba(0,0,0,0.5); margin-top: -3.5px; cursor: pointer; }\n                input[type=range]::-moz-range-track { width: 100%; height: 3px; background: #595959; border-radius: 9999px; }\n                input[type=range]::-moz-range-thumb { width: 10px; height: 10px; border: none; border-radius: 50%; background: white; box-shadow: 0px 1px 3px rgba(0,0,0,0.5); cursor: pointer; }\n\n                .dark-scrollbar { scrollbar-width: thin; scrollbar-color: #333333 transparent; }\n                .dark-scrollbar::-webkit-scrollbar { width: 1px; }\n                .dark-scrollbar::-webkit-scrollbar-track { background: transparent; }\n                .dark-scrollbar::-webkit-scrollbar-thumb { background: #333333; border-radius: 9999px; }\n                .dark-scrollbar::-webkit-scrollbar-thumb:hover { background: #4d4d4d; }\n\n                @keyframes dropdown-enter { from { opacity: 0; transform: scale(0.95) translateY(-5px); } to { opacity: 1; transform: scale(1) translateY(0); } }\n                .animate-dropdown { animation: dropdown-enter 0.15s ease-out forwards; }\n\n                @keyframes layer-enter { from { opacity: 0; transform: translateY(-4px); } to { opacity: 1; transform: translateY(0); } }\n                .animate-layer { animation: layer-enter 0.2s ease-out forwards; }\n\n                .braille-loader { display: flex; gap: 6px; align-items: center; }\n                .braille-loader span { width: 6px; height: 6px; border-radius: 50%; background: rgba(255,255,255,0.5); animation: braille-bounce 1.2s cubic-bezier(0.4,0,0.2,1) infinite; }\n                .braille-loader span:nth-child(1) { animation-delay: 0s; }\n                .braille-loader span:nth-child(2) { animation-delay: 0.15s; }\n                .braille-loader span:nth-child(3) { animation-delay: 0.3s; }\n                .braille-loader span:nth-child(4) { animation-delay: 0.45s; }\n                @keyframes braille-bounce { 0%,60%,100% { opacity: 0.2; transform: scale(0.8); } 30% { opacity: 1; transform: scale(1.2); } }\n\n                html, body, #root {\n                    margin: 0; padding: 0; width: 100%; height: 100%;\n                    background: #0e0e0e;\n                    font-family: 'Google Sans Text', 'Google Sans', -apple-system, BlinkMacSystemFont, sans-serif;\n                    -webkit-font-smoothing: antialiased;\n                    -moz-osx-font-smoothing: grayscale;\n                }\n            `;
            document.head.appendChild(style);
        }

        return () => {
            preconnect1.remove();
            preconnect2.remove();
            textFontLink.remove();
        };
    }, []);
}

export default function App() {
    useGlobalStyles();

    const [bgMedia, setBgMedia] = useState<MediaAsset | null>(null);
    const [duration, setDuration] = useState(8);
    const [textConfigs, setTextConfigs] = useState<TextConfig[]>([
        {
            id: '1',
            content: 'Type' + String.fromCharCode(10) + 'Overlays',
            fontFamily: "'Instrument Sans', sans-serif",
            fontSize: 84,
            fontWeight: 500,
            letterSpacing: 0,
            lineHeight: 1,
            textAlign: 'center',
            color: '#ffffff',
            backgroundColor: '#000000',
            bgOpacity: 0,
            position: { x: 50, y: 50 },
            effect: 'blur-in',
            granularity: 'word',
            easing: 'smooth',
            speed: 1,
            stackTransition: 'blur',
            duration: 2200,
            delay: 140,
            inDuration: 800,
            outDuration: 0,
            intensity: 50,
        }
    ]);
    const [selectedTextId, setSelectedTextId] = useState<string | null>('1');
    const [isPlaying, setIsPlaying] = useState(false);
    const [isRendering, setIsRendering] = useState(false);
    const [renderProgress, setRenderProgress] = useState(0);
    const [exportedMedia, setExportedMedia] = useState<{ dataUrl: string, mimeType: string } | null>(null);
    const prevExportUrl = useRef<string | null>(null);
    const prevMediaUrl = useRef<string | null>(null);
    const abortControllerRef = useRef<AbortController | null>(null);
    const [key, setKey] = useState(0);

    const handleDeleteLayer = useCallback((id: string) => {
        if (textConfigs.length <= 1) return;
        if (selectedTextId === id) {
            // Pick the next layer, or the previous one if this is the last
            const idx = textConfigs.findIndex(c => c.id === id);
            const next = textConfigs[idx + 1] ?? textConfigs[idx - 1];
            setSelectedTextId(next.id);
        }
        setTextConfigs(prev => prev.filter(c => c.id !== id));
    }, [textConfigs, selectedTextId]);

    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            const activeElement = document.activeElement;
            const isInput = activeElement &&
                (activeElement.tagName === 'INPUT' ||
                    activeElement.tagName === 'TEXTAREA' ||
                    (activeElement instanceof HTMLElement && activeElement.isContentEditable));

            if (isInput) return;

            if (e.key === ' ' || e.code === 'Space') {
                e.preventDefault();
                setIsPlaying(prev => !prev);
            } else if (e.key === 'Backspace' || e.key === 'Delete') {
                if (selectedTextId) {
                    e.preventDefault();
                    handleDeleteLayer(selectedTextId);
                }
            }
        };

        window.addEventListener('keydown', handleKeyDown);
        return () => {
            window.removeEventListener('keydown', handleKeyDown);
        };
    }, [selectedTextId, handleDeleteLayer]);

    const handleSelectMedia = async () => {
        try {
            const media = await Flow.media.select({ filter: 'all' });
            if (media) {
                const bytes = Uint8Array.from(atob(media.base64), c => c.charCodeAt(0));
                const blob = new Blob([bytes], { type: media.mimeType });
                const blobUrl = URL.createObjectURL(blob);
                if (prevMediaUrl.current) URL.revokeObjectURL(prevMediaUrl.current);
                prevMediaUrl.current = blobUrl;
                setBgMedia({ type: media.type, dataUrl: blobUrl, mimeType: media.mimeType });
                setIsPlaying(true);
                timeController.setTime(0);
            }
        } catch (err) {
            console.error('Failed to select media', err);
        }
    };

    const handleAddLayer = useCallback(() => {
        const newId = Math.random().toString(36).substr(2, 9);

        // Find where to put the new layer: after the selected layer or at the very end
        const activeLayer = textConfigs.find(c => c.id === selectedTextId);
        let newDelay = 140;

        if (activeLayer) {
            newDelay = activeLayer.delay + activeLayer.duration;
        } else if (textConfigs.length > 0) {
            newDelay = Math.max(...textConfigs.map(c => c.delay + c.duration), 0);
        }

        // Safety check against duration
        if (newDelay >= duration * 1000) {
            newDelay = Math.max(0, (duration * 1000) - 2200);
        }

        const lastLayer = textConfigs[textConfigs.length - 1];
        const newLayer: TextConfig = {
            ...(lastLayer || {
                fontFamily: "'Instrument Sans', sans-serif",
                fontSize: 84,
                fontWeight: 500,
                letterSpacing: 0,
                lineHeight: 1,
                textAlign: 'center',
                color: '#ffffff',
                backgroundColor: '#000000',
                bgOpacity: 0,
                effect: 'blur-in',

                granularity: 'word',
                easing: 'smooth',
                speed: 1,
                stackTransition: 'blur',
                intensity: 50,
            }),
            id: newId,
            content: 'New Layer',
            position: { x: 50, y: 50 },
            delay: newDelay,
            duration: 2200,
            inDuration: 800,
            outDuration: 0,
            intensity: 50,
        };
        setTextConfigs(prev => [...prev, newLayer]);
        setSelectedTextId(newId);

        // Seek playhead to just after the new layer's in-animation (same logic as clicking a block in the timeline)
        const inDuration = newLayer.inDuration ?? 800;
        const visibleTime = (newDelay + inDuration + 100) / 1000;
        const endTime = (newDelay + 2200) / 1000;
        timeController.setTime(Math.min(visibleTime, endTime, duration));
    }, [selectedTextId, textConfigs, duration]);


    const handleExport = async () => {

        // Pause so Stage.tsx's updateLoop doesn't override the TimeController
        setIsPlaying(false);

        setIsRendering(true);
        setRenderProgress(0);

        const controller = new AbortController();
        abortControllerRef.current = controller;

        try {
            const result = await renderVideo(bgMedia, textConfigs, (p) => setRenderProgress(p), controller.signal, duration);
            // Revoke previous export blob URL to free memory
            if (prevExportUrl.current) URL.revokeObjectURL(prevExportUrl.current);
            prevExportUrl.current = result.dataUrl;
            setExportedMedia({ dataUrl: result.dataUrl, mimeType: result.mimeType });
        } catch (err) {
            if (err instanceof Error && err.message === "Render cancelled") {
                console.log('Render cancelled by user');
            } else {
                console.error('Render failed', err);
            }
        } finally {
            setIsRendering(false);
            setIsPlaying(false);
            abortControllerRef.current = null;
        }
    };

    const updateTextConfig = useCallback((updates: Partial<TextConfig>, id?: string) => {
        const targetId = id || selectedTextId;
        setTextConfigs(prev => prev.map(c =>
            c.id === targetId ? { ...c, ...updates } : c
        ));
    }, [selectedTextId]);

    const batchUpdateTextConfigs = useCallback((updates: Array<{ id: string; changes: Partial<TextConfig> }>) => {
        setTextConfigs(prev => prev.map(c => {
            const update = updates.find(u => u.id === c.id);
            return update ? { ...c, ...update.changes } : c;
        }));
    }, []);

    const selectedConfig = textConfigs.find(c => c.id === selectedTextId) || null;

    const handleRestart = useCallback(() => {
        setKey(prev => prev + 1);
        timeController.setTime(0);
        if (isPlaying) setIsPlaying(false);
        setTimeout(() => setIsPlaying(true), 50);
    }, [isPlaying]);

    const handleTimelineSeek = useCallback((time: number) => {
        timeController.setTime(time);
    }, []);

    return (
        <div className="fixed inset-0 w-screen h-screen bg-[#0a0a0a] text-[#ededed] flex overflow-hidden font-sans">
            {/* Main Workspace */}
            <div className="flex-1 flex flex-col min-w-0 h-full p-8 lg:p-12 overflow-hidden">
                {/* Stage Container with defined space */}
                <div className="flex-1 flex items-center justify-center min-h-0 relative mb-8 overflow-hidden">
                    <Stage
                        media={bgMedia}
                        configs={textConfigs}
                        selectedId={isRendering ? null : selectedTextId}
                        isPlaying={isPlaying}
                        animationKey={key}
                        onUpdatePosition={(pos) => updateTextConfig({ position: pos })}
                        onMetadataLoaded={(d) => setDuration(d)}
                        onSelectLayer={setSelectedTextId}
                        placeholderDuration={8}
                    />
                </div>

                {/* Timeline Area - Fixed height, will not overlap */}
                <div className="shrink-0 w-full max-w-5xl mx-auto px-6">
                    <Timeline
                        duration={duration}
                        configs={textConfigs}
                        selectedId={selectedTextId}
                        isPlaying={isPlaying}
                        onPlayPause={() => setIsPlaying(!isPlaying)}
                        onRestart={handleRestart}
                        onSeek={handleTimelineSeek}
                        onUpdateConfig={updateTextConfig}
                        onBatchUpdate={batchUpdateTextConfigs}
                        onSelectLayer={setSelectedTextId}
                    />
                </div>
            </div>

            <MemoizedSidebar
                config={selectedConfig}
                allConfigs={textConfigs}
                onUpdate={updateTextConfig}
                onSelectMedia={handleSelectMedia}
                onDeleteLayer={handleDeleteLayer}
                onSelectLayer={setSelectedTextId}
                onAddLayer={handleAddLayer}
                onExport={handleExport}
                isRendering={isRendering}
                renderProgress={renderProgress}
                hasMedia={!!bgMedia}
            />

            {/* Export Popup */}
            {exportedMedia && (
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-8" onClick={() => setExportedMedia(null)}>
                    <div className="bg-[#0a0a0a] border border-[rgba(218,220,224,0.15)] rounded-xl p-5 shadow-2xl max-w-2xl w-full flex flex-col gap-5" onClick={(e) => e.stopPropagation()}>
                        <div className="flex items-center justify-between">
                            <h2 className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px]">Render Complete</h2>
                            <button
                                onClick={() => setExportedMedia(null)}
                                className="text-[rgba(218,220,224,0.35)] hover:text-white transition-colors p-1"
                            >
                                <Icon name="close" size={16} />
                            </button>
                        </div>

                        <div className="rounded-xl overflow-hidden bg-black border border-[rgba(218,220,224,0.15)] flex items-center justify-center min-h-[300px]">
                            {exportedMedia.mimeType.startsWith('video/') ? (
                                <video
                                    src={exportedMedia.dataUrl}
                                    controls
                                    autoPlay
                                    loop
                                    className="max-h-[60vh] max-w-full object-contain"
                                />
                            ) : (
                                <img
                                    src={exportedMedia.dataUrl}
                                    alt="Exported result"
                                    className="max-h-[60vh] max-w-full object-contain"
                                />
                            )}
                        </div>

                        <div className="flex gap-[5px] pt-2">
                            <button
                                onClick={() => setExportedMedia(null)}
                                className="flex-1 h-[34px] rounded-xl border border-[rgba(218,220,224,0.15)] hover:bg-white/5 active:bg-white/10 text-[12px] font-medium text-white tracking-[0.1px] transition-all cursor-pointer select-none"
                            >
                                Close
                            </button>
                        </div>
                    </div>
                </div>
            )}
            {isRendering && (
                <div className="fixed inset-0 z-[100] bg-black/80 backdrop-blur-sm flex items-center justify-center cursor-wait">
                    <div className="flex flex-col items-center gap-5">
                        <div className="braille-loader" aria-label="Rendering">
                            <span /><span /><span /><span />
                        </div>
                        <span className="text-[14px] font-medium text-white tracking-[0.1px]">
                            Rendering {Math.round(renderProgress * 100)}%
                        </span>
                        <span className="text-[12px] text-white/60 tracking-[0.1px] max-w-[240px] text-center leading-relaxed">
                            This may take a minute.<br />Don&apos;t switch tabs.
                        </span>
                        <button
                            onClick={() => abortControllerRef.current?.abort()}
                            className="mt-2 h-[34px] px-6 rounded-lg border border-white/30 hover:bg-white/10 active:bg-white/20 text-[12px] font-medium text-white/80 tracking-[0.1px] transition-all cursor-pointer select-none"
                        >
                            Cancel
                        </button>
                    </div>
                </div>
            )}
        </div>
    );
}

import React, { useEffect, useRef, useMemo, memo } from 'react';
import { createTimeline, stagger, splitText, steps, spring } from 'animejs';
import { TextConfig, FONTS, KINETIC_EFFECTS } from '../types';
import { timeController } from '../services/TimeController';

interface AnimatedTextProps {
    config: TextConfig;
    isPlaying: boolean;
    animationKey: number;
    selectedId: string | null;
    onSelectLayer: (e: React.MouseEvent, id: string) => void;
}

const FONT_FAMILIES = FONTS.map(f => f.family);

// Module-level style injection — runs once, not per effect rebuild (#5)
const STYLE_ID = 'typestroke-animation-styles';
if (typeof document !== 'undefined' && !document.getElementById(STYLE_ID)) {
    const styleEl = document.createElement('style');
    styleEl.id = STYLE_ID;
    styleEl.innerHTML = `\n        .stack-container { display: grid; place-items: center; width: 100%; height: 100%; }\n        .stack-item { grid-area: 1 / 1 / 2 / 2; opacity: 0; }\n        .line-wrap { display: block; }\n    `;
    document.head.appendChild(styleEl);
}

function seededRandom(seed: number): number {
    const x = Math.sin(seed * 12.9898 + 78.233) * 43758.5453;
    return x - Math.floor(x);
}

function applyKineticFrame(effect: string, elements: HTMLElement[], localTimeMs: number, speed: number, intensity: number, lineIndices: number[] = []) {
    const n = elements.length;
    if (n === 0) return;
    const s = speed || 1;
    const amp = (intensity || 50) / 50;

    if (effect === 'wave') {
        const freq = s * 0.008;
        const maxY = amp * 12;
        elements.forEach((el, i) => {
            const idx = lineIndices.length > 0 ? lineIndices[i] : i;
            const y = Math.sin(localTimeMs * freq + idx * 0.7) * maxY;
            el.style.transform = `translateY(${y}px)`;
        });
    } else if (effect === 'wiggle') {
        const updateRate = Math.max(30, 200 / s);
        const tick = Math.floor(localTimeMs / updateRate);
        const maxShift = amp * 4;
        elements.forEach((el, i) => {
            const sx = seededRandom(tick * 137 + i * 31);
            const sy = seededRandom(tick * 251 + i * 53);
            el.style.transform = `translate(${(sx - 0.5) * maxShift * 2}px, ${(sy - 0.5) * maxShift * 2}px)`;
        });
    } else if (effect === 'font-shuffle') {
        const interval = Math.max(50, 400 / s);
        const tick = Math.floor(localTimeMs / interval);
        elements.forEach((el, i) => {
            const fontIdx = Math.floor(seededRandom(tick * 73 + i * 17) * FONT_FAMILIES.length);
            el.style.fontFamily = FONT_FAMILIES[fontIdx];
        });
    }
}

function getAnimParts(
    h2: HTMLElement,
    granularity: string,
    root: HTMLElement,
    effect: string
): { parts: HTMLElement[] | null; splitter: any } {
    if (granularity === 'line') {
        // Lines are manually split (anime.js lines are async/unreliable for seek)
        const lineEls = root.querySelectorAll('.line-wrap');
        return {
            parts: lineEls.length > 0 ? Array.from(lineEls) as HTMLElement[] : null,
            splitter: null
        };
    }

    // Use wrap:'clip' only for slide-up (text slides in from below, needs clip mask).
    // slide-fade is opacity-only — clip would cut off font descenders/swashes.
    const needsClip = effect === 'slide-up';
    const splitKey = granularity === 'word' ? 'words' : 'chars';

    const splitOpts: any = {};
    if (splitKey === 'words') {
        splitOpts.words = needsClip ? { wrap: 'clip' } : true;
    } else {
        splitOpts.chars = needsClip ? { wrap: 'clip' } : true;
    }

    const splitter = splitText(h2, splitOpts);
    const parts = splitter[splitKey as 'chars' | 'words'];
    return {
        parts: (parts && parts.length > 0) ? Array.from(parts) as HTMLElement[] : null,
        splitter
    };
}

/** Shared stagger timing calculation used by blur-in, slide-up, slide-fade (#10) */
function computeStagger(n: number, inDur: number, granularity: string) {
    const perDur = Math.min(
        granularity === 'line' ? Math.max(200, inDur * 0.5)
        : granularity === 'char' ? Math.max(80, inDur * 0.3)
        : Math.max(150, inDur * 0.4),
        inDur
    );
    const sd = n > 1 ? Math.max(0, (inDur - perDur) / (n - 1)) : 0;
    return { perDur, sd };
}

const AnimatedTextComponent: React.FC<AnimatedTextProps> = ({ config, isPlaying, animationKey, selectedId, onSelectLayer }) => {
    const rootRef = useRef<HTMLDivElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);
    const timelineRef = useRef<any>(null);
    const splitterRef = useRef<any>(null);
    const kineticPartsRef = useRef<HTMLElement[]>([]);
    const kineticTypeRef = useRef<string | null>(null);
    const kineticLineIndicesRef = useRef<number[]>([]);
    const configRef = useRef(config);
    configRef.current = config;

    const styles = useMemo(() => ({
        fontFamily: config.fontFamily,
        fontSize: `${config.fontSize}px`,
        fontWeight: config.fontWeight,
        letterSpacing: `${config.letterSpacing}px`,
        textAlign: config.textAlign as any,
        color: config.color,
        lineHeight: config.lineHeight,
        whiteSpace: 'pre-wrap' as const,
    }), [config.fontFamily, config.fontSize, config.fontWeight, config.letterSpacing, config.textAlign, config.color, config.lineHeight]);

    // Build animation
    useEffect(() => {
        if (!rootRef.current) return;

        // Clean up previous splitter to avoid DOM leaks (#4)
        if (splitterRef.current) {
            try { splitterRef.current.revert(); } catch {}
            splitterRef.current = null;
        }

        const content = config.content || '';
        const speedMul = 1 / (config.speed || 1);
        const inEase = config.easing === 'linear' ? 'linear' : spring({ bounce: 0.5, duration: 628 });
        const outEase = config.easing === 'linear' ? 'linear' : spring({ bounce: 0, duration: 400 });
        const granularity = config.granularity || 'word';
        const isKinetic = KINETIC_EFFECTS.has(config.effect);
        const isStackLayout = config.effect === 'sequential-stack';

        // Reset
        kineticPartsRef.current = [];
        kineticTypeRef.current = null;
        kineticLineIndicesRef.current = [];
        timelineRef.current = null;

        // === HTML Generation ===
        if (isStackLayout) {
            let segments: string[];
            if (granularity === 'char') {
                segments = content.split('').filter(c => c.trim().length > 0);
            } else if (granularity === 'line') {
                segments = content.split(String.fromCharCode(10)).filter(l => l.trim().length > 0);
                if (segments.length < 2) segments = content.split(' ').filter(w => w.length > 0);
            } else {
                segments = content.split(' ').filter(w => w.length > 0);
            }
            rootRef.current.innerHTML = '<' + 'div class="stack-container">' + segments.map(s => '<' + 'h2 class="stack-item">' + s + '<' + '/h2>').join('') + '<' + '/div>';
        } else if (granularity === 'line' && config.effect !== 'none') {
            const lines = content.split(String.fromCharCode(10));
            rootRef.current.innerHTML = '<' + 'h2>' + lines.map(l => '<' + 'span class="line-wrap">' + (l || '&nbsp;') + '<' + '/span>').join('') + '<' + '/h2>';
        } else {
            rootRef.current.innerHTML = '<' + 'h2>' + content + '<' + '/h2>';
        }

        const h2 = rootRef.current.querySelector('h2')!;
        const applyStyles = (el: HTMLElement) => {
            el.style.margin = '0'; el.style.padding = '0';
            el.style.fontSize = 'inherit'; el.style.fontWeight = 'inherit';
            el.style.fontFamily = 'inherit'; el.style.color = 'inherit';
            el.style.textAlign = 'inherit'; el.style.letterSpacing = 'inherit';
            el.style.lineHeight = config.lineHeight.toString();
            el.style.whiteSpace = 'pre-wrap';
        };
        if (isStackLayout) {
            rootRef.current.querySelectorAll('.stack-item').forEach(el => applyStyles(el as HTMLElement));
        } else {
            applyStyles(h2);
        }

        if (config.effect === 'none') return;

        // === Kinetic effects: store refs, no timeline ===
        if (isKinetic) {
            kineticTypeRef.current = config.effect;
            // wave, wiggle, font-shuffle: split into chars/words
            const { parts, splitter: sp } = getAnimParts(h2, granularity, rootRef.current, config.effect);
            kineticPartsRef.current = parts || [];
            splitterRef.current = sp;

            // Compute per-line indices for wave sync (so multi-lines wave in unison)
            if (config.effect === 'wave' && parts && parts.length > 0) {
                const indices: number[] = [];
                let currentTop = -Infinity;
                let lineIdx = 0;
                parts.forEach(el => {
                    const top = el.offsetTop;
                    if (Math.abs(top - currentTop) > 2) {
                        currentTop = top;
                        lineIdx = 0;
                    }
                    indices.push(lineIdx);
                    lineIdx++;
                });
                kineticLineIndicesRef.current = indices;
            } else {
                kineticLineIndicesRef.current = [];
            }
            return;
        }

        // === Timeline-based effects ===
        const tl = createTimeline({ autoplay: false });
        const inDur = config.inDuration * speedMul;
        const outDur = config.outDuration * speedMul;
        const inStart = config.delay;
        const outStart = config.delay + config.duration - outDur;

        if (config.effect === 'sequential-stack') {
            const items = rootRef.current.querySelectorAll('.stack-item');
            const effectiveDuration = config.duration / (config.speed || 1);
            const step = effectiveDuration / Math.max(items.length, 1);
            const transition = config.stackTransition || 'blur';

            if (transition === 'blur') {
                tl.add(items, { opacity: [0, 1], scale: [0.8, 1], filter: ['blur(10px)', 'blur(0px)'], duration: Math.min(300, step * 0.4), ease: inEase, delay: stagger(step, { start: config.delay }) });
                items.forEach((item, i) => { if (i < items.length - 1) tl.add(item, { opacity: 0, scale: 1.2, filter: 'blur(5px)', duration: Math.min(200, step * 0.3), ease: outEase }, config.delay + (step * (i + 1)) - Math.min(100, step * 0.15)); });
            } else if (transition === 'cut') {
                tl.add(items, { opacity: [0, 1], duration: 1, ease: steps(1), delay: stagger(step, { start: config.delay }) });
                items.forEach((item, i) => { if (i < items.length - 1) tl.add(item, { opacity: 0, duration: 1, ease: steps(1) }, config.delay + (step * (i + 1))); });
            } else if (transition === 'fade') {
                tl.add(items, { opacity: [0, 1], duration: Math.min(250, step * 0.4), ease: inEase, delay: stagger(step, { start: config.delay }) });
                items.forEach((item, i) => { if (i < items.length - 1) tl.add(item, { opacity: 0, duration: Math.min(200, step * 0.3), ease: outEase }, config.delay + (step * (i + 1)) - Math.min(100, step * 0.15)); });
            }
        } else {
            // Shared logic for blur-in, typewriter, slide-up, slide-fade
            const { parts, splitter: sp } = getAnimParts(h2, granularity, rootRef.current, config.effect);
            splitterRef.current = sp;
            if (parts && parts.length > 0) {
                const n = parts.length;

                if (config.effect === 'typewriter') {
                    // Each char snaps from invisible to visible.
                    // Stagger so the last char starts well within inDur (not at the very edge).
                    const stepDur = 1;
                    const staggerInt = n > 1 ? (inDur - stepDur) / (n - 1) : 0;
                    tl.add(parts, { opacity: [0, 1], ease: steps(1), duration: stepDur, delay: stagger(staggerInt) }, inStart);
                    if (outDur > 0) {
                        const outStagger = n > 1 ? (outDur - stepDur) / (n - 1) : 0;
                        tl.add(parts, { opacity: [1, 0], duration: 1, ease: steps(1), delay: stagger(outStagger) }, outStart);
                    }

                } else if (config.effect === 'blur-in') {
                    const { perDur, sd } = computeStagger(n, inDur, granularity);
                    tl.add(parts, { opacity: [0, 1], y: [20, 0], filter: ['blur(10px)', 'blur(0px)'], ease: inEase, duration: perDur, delay: stagger(sd) }, inStart);
                    if (outDur > 0) { const { perDur: od, sd: osd } = computeStagger(n, outDur, granularity); tl.add(parts, { opacity: [1, 0], filter: ['blur(0px)', 'blur(10px)'], y: [0, -20], duration: od, ease: outEase, delay: stagger(osd) }, outStart); }

                } else if (config.effect === 'slide-up') {
                    const { perDur, sd } = computeStagger(n, inDur, granularity);
                    tl.add(parts, { opacity: [0, 1], y: ['150%', '0%'], ease: inEase, duration: perDur, delay: stagger(sd) }, inStart);
                    if (outDur > 0) { const { perDur: od, sd: osd } = computeStagger(n, outDur, granularity); tl.add(parts, { opacity: [1, 0], y: ['0%', '-150%'], duration: od, ease: outEase, delay: stagger(osd) }, outStart); }

                } else if (config.effect === 'slide-fade') {
                    const { perDur, sd } = computeStagger(n, inDur, granularity);
                    tl.add(parts, { opacity: [0, 1], ease: inEase, duration: perDur, delay: stagger(sd) }, inStart);
                    if (outDur > 0) { const { perDur: od, sd: osd } = computeStagger(n, outDur, granularity); tl.add(parts, { opacity: [1, 0], duration: od, ease: outEase, delay: stagger(osd) }, outStart); }
                }
            }
        }

        timelineRef.current = tl;
        tl.seek(timeController.getTime() * 1000);

        return () => {
            if (timelineRef.current) timelineRef.current.pause();
            if (splitterRef.current) {
                try { splitterRef.current.revert(); } catch {}
                splitterRef.current = null;
            }
        };
    }, [config.content, config.effect, config.granularity, config.easing, config.speed, config.stackTransition, config.inDuration, config.outDuration, config.delay, config.duration, config.intensity, config.lineHeight, config.fontSize, config.fontFamily, config.fontWeight, config.letterSpacing, config.color, config.textAlign, animationKey]);

    // Time subscription
    useEffect(() => {
        const update = (time: number) => {
            const c = configRef.current;
            const timeMs = time * 1000;
            if (timelineRef.current) timelineRef.current.seek(timeMs);

            // Kinetic per-frame computation
            const kType = kineticTypeRef.current;
            if (kType && kineticPartsRef.current.length > 0) {
                const localTime = timeMs - c.delay;
                if (localTime >= 0 && localTime <= c.duration) {
                    applyKineticFrame(kType, kineticPartsRef.current, localTime, c.speed, c.intensity, kineticLineIndicesRef.current);
                }
            }

            if (containerRef.current) {
                const isVisible = timeMs >= c.delay && timeMs <= (c.delay + c.duration);
                containerRef.current.style.opacity = isVisible ? '1' : '0';
                containerRef.current.style.pointerEvents = isVisible ? 'auto' : 'none';
            }
        };
        update(timeController.getTime());
        const unsubscribe = timeController.subscribe(update);
        return unsubscribe;
    }, [config.delay, config.duration]);

    return (
        <div
            ref={containerRef}
            onMouseDown={(e) => onSelectLayer(e, config.id)}
            className={`absolute cursor-move active:cursor-grabbing p-2 transition-shadow ${selectedId === config.id ? 'ring-1 ring-white/20 rounded-xl' : ''}`}
            style={{
                left: `${config.position.x}%`,
                top: `${config.position.y}%`,
                transform: `translate(-${config.position.x}%, -${config.position.y}%)`,
                width: 'max-content',
                zIndex: selectedId === config.id ? 20 : 10,
                opacity: 0,
                pointerEvents: 'none'
            }}
        >
            <div ref={rootRef} style={styles} />
        </div>
    );
};

export const AnimatedText = memo(AnimatedTextComponent);

import React, { useEffect, useRef, memo } from 'react';
import { AnimationEffect, AnimationGranularity, AnimationEasing, StackTransition, TextConfig,
         KINETIC_EFFECTS, TRANSITION_EFFECTS, EFFECTS_WITH_SPEED, EFFECTS_WITH_AMPLITUDE, EFFECTS_WITH_EASING } from '../types';
import { SegmentedToggle, RangeSlider, SectionLabel } from './Primitives';

interface EffectPickerProps {
    config: TextConfig;
    onUpdate: (updates: Partial<TextConfig>) => void;
}

const TRANSITION_LIST: { id: AnimationEffect; label: string }[] = [
    { id: 'none', label: 'None' },
    { id: 'blur-in', label: 'Blur' },
    { id: 'slide-up', label: 'Slide Up' },
    { id: 'slide-fade', label: 'Fade' },
    { id: 'typewriter', label: 'Appear' },
];

const KINETIC_LIST: { id: AnimationEffect; label: string }[] = [
    { id: 'sequential-stack', label: 'Stack' },
    { id: 'wave', label: 'Wave' },
    { id: 'wiggle', label: 'Wiggle' },
    { id: 'font-shuffle', label: 'Shuffle' },
];



/* ─── Mini Preview ─── */
const EffectPreview: React.FC<{
    effect: AnimationEffect; text: string; fontFamily: string; isSelected: boolean; onClick: () => void;
}> = memo(({ effect, text, fontFamily, isSelected, onClick }) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const words = text.split(' ').filter(w => w.length > 0);
    const previewWords = words.length >= 2 ? words.slice(0, 3) : ['Text', 'Here'];
    const previewText = (words[0] || 'Text').slice(0, 6);

    useEffect(() => {
        const el = containerRef.current;
        if (!el) return;
        const styleId = 'effect-preview-keyframes-v3';
        if (!document.getElementById(styleId)) {
            const style = document.createElement('style');
            style.id = styleId;
            style.textContent = `\n                @keyframes ep-blur { 0%{opacity:0;filter:blur(6px);transform:translateY(4px)} 20%{opacity:1;filter:blur(0);transform:translateY(0)} 80%{opacity:1} 100%{opacity:0;filter:blur(6px);transform:translateY(-4px)} }\n                @keyframes ep-type { 0%{opacity:0} 12%{opacity:1} 75%{opacity:1} 76%{opacity:0} 100%{opacity:0} }\n                @keyframes ep-slide { 0%{opacity:0;transform:translateY(150%)} 20%{opacity:1;transform:translateY(0)} 80%{opacity:1;transform:translateY(0)} 100%{opacity:0;transform:translateY(-150%)} }\n                @keyframes ep-fade { 0%{opacity:0} 20%{opacity:1} 80%{opacity:1} 100%{opacity:0} }\n                @keyframes ep-stack-2 { 0%{opacity:0} 0.1%{opacity:1} 50%{opacity:1} 50.1%{opacity:0} 100%{opacity:0} }\n                @keyframes ep-stack-3 { 0%{opacity:0} 0.1%{opacity:1} 33.3%{opacity:1} 33.4%{opacity:0} 100%{opacity:0} }\n                @keyframes ep-wave { 0%{transform:translateY(0)} 25%{transform:translateY(-4px)} 50%{transform:translateY(0)} 75%{transform:translateY(4px)} 100%{transform:translateY(0)} }\n                @keyframes ep-wiggle { 0%{transform:translate(0,0)} 20%{transform:translate(2px,-1px)} 40%{transform:translate(-1px,2px)} 60%{transform:translate(1px,1px)} 80%{transform:translate(-2px,0)} 100%{transform:translate(0,0)} }\n                @keyframes ep-shuffle { 0%{font-family:'Instrument Sans',sans-serif} 20%{font-family:'Instrument Serif',serif} 40%{font-family:'Space Mono',monospace} 60%{font-family:'Danfo',serif} 80%{font-family:'Faculty Glyphic',sans-serif} 100%{font-family:'Instrument Sans',sans-serif} }\n            `;
            document.head.appendChild(style);
        }

        const chars = previewText.split('');
        const dur = 2500;
        let html = '';

        const charAnim = (kf: string, addStyle = '') =>
            chars.map((c, i) => {
                const d = (i / chars.length) * (dur * 0.3);
                return `${'<'}span style="display:inline-block;animation:${kf} ${dur}ms ${d}ms ease-out infinite;opacity:0;${addStyle}"${'>'} ${c === ' ' ? '&nbsp;' : c}<${'/'}span>`;
            }).join('');

        const stackAnim = (kf: string) => {
            const sw = previewWords.map(w => w.slice(0, 8));
            return `${'<'}div style="display:grid;place-items:center;width:100%;height:100%"${'>'}` +
                sw.map((w, i) => `${'<'}span style="grid-area:1/1/2/2;animation:${kf} ${dur}ms ${(i / sw.length) * dur}ms ease-out infinite;opacity:0"${'>'} ${w}<${'/'}span>`).join('') + `<${'/'}div>`;
        };

        if (effect === 'none') html = `${'<'}span${'>'} ${previewText}<${'/'}span>`;
        else if (effect === 'blur-in') html = charAnim('ep-blur');
        else if (effect === 'typewriter') html = charAnim('ep-type');
        else if (effect === 'slide-up') html = charAnim('ep-slide');
        else if (effect === 'slide-fade') html = charAnim('ep-fade');
        else if (effect === 'sequential-stack') html = stackAnim(`ep-stack-${previewWords.length}`);

        else if (effect === 'wave') html = chars.map((c, i) => `${'<'}span style="display:inline-block;animation:ep-wave 800ms ${i * 100}ms ease-in-out infinite"${'>'} ${c === ' ' ? '&nbsp;' : c}<${'/'}span>`).join('');
        else if (effect === 'wiggle') html = chars.map((c, i) => `${'<'}span style="display:inline-block;animation:ep-wiggle 300ms ${i * 30}ms linear infinite"${'>'} ${c === ' ' ? '&nbsp;' : c}<${'/'}span>`).join('');
        else if (effect === 'font-shuffle') html = chars.map((c) => `${'<'}span style="display:inline-block;animation:ep-shuffle 1200ms linear infinite"${'>'} ${c === ' ' ? '&nbsp;' : c}<${'/'}span>`).join('');

        el.innerHTML = html;
    }, [effect, previewText, previewWords.join(',')]);

    return (
        <button onClick={onClick}
            className={`flex flex-col items-center gap-1.5 rounded-lg border transition-all p-1.5\n                ${isSelected ? 'border-white/30 bg-white/[0.08] ring-1 ring-white/10' : 'border-white/[0.06] bg-white/[0.02] hover:border-white/[0.15] hover:bg-white/[0.04]'}`}>
            <div ref={containerRef}
                className="w-full h-[42px] flex items-center justify-center overflow-hidden rounded-md text-[13px] text-white/80"
                style={{ fontFamily, letterSpacing: '-0.5px', fontWeight: 500 }} />
            <span className={`text-[9px] tracking-wide font-medium transition-colors ${isSelected ? 'text-white/70' : 'text-white/25'}`}>
                {[...TRANSITION_LIST, ...KINETIC_LIST].find(e => e.id === effect)?.label}
            </span>
        </button>
    );
});



/* ─── Default settings per effect — applied when switching ─── */
const EFFECT_DEFAULTS: Partial<Record<AnimationEffect, Partial<TextConfig>>> = {
    'none':             { granularity: 'word', easing: 'smooth', speed: 1, intensity: 50 },
    'blur-in':          { granularity: 'word', easing: 'smooth', speed: 1, intensity: 50 },
    'typewriter':       { granularity: 'char', easing: 'linear', speed: 1, intensity: 50 },
    'slide-up':         { granularity: 'word', easing: 'smooth', speed: 1, intensity: 50 },
    'slide-fade':       { granularity: 'word', easing: 'smooth', speed: 1, intensity: 50 },
    'sequential-stack': { granularity: 'word', easing: 'smooth', speed: 1, intensity: 50, stackTransition: 'cut' },
    'wave':             { granularity: 'char', easing: 'smooth', speed: 1, intensity: 50 },
    'wiggle':           { granularity: 'char', easing: 'linear', speed: 1, intensity: 50 },
    'font-shuffle':     { granularity: 'char', easing: 'linear', speed: 2, intensity: 50 },
};

/* ─── Main Export ─── */
export const EffectPicker: React.FC<EffectPickerProps> = ({ config, onUpdate }) => {
    const showSpeed = EFFECTS_WITH_SPEED.has(config.effect);
    const showAmplitude = EFFECTS_WITH_AMPLITUDE.has(config.effect);
    const showEasing = EFFECTS_WITH_EASING.has(config.effect);
    const showControls = config.effect !== 'none';
    const isKinetic = KINETIC_EFFECTS.has(config.effect);
    const isStack = config.effect === 'sequential-stack';

    const handleEffectClick = (id: AnimationEffect) => {
        const updates: Partial<TextConfig> = { effect: id, ...(EFFECT_DEFAULTS[id] || {}) };
        if (KINETIC_EFFECTS.has(id) || id === 'sequential-stack') {
            updates.inDuration = 0;
            updates.outDuration = 0;
        }
        if (TRANSITION_EFFECTS.has(id) && config.inDuration === 0 && config.outDuration === 0) {
            updates.inDuration = 800;
        }
        onUpdate(updates);
    };

    return (
        <div className="space-y-3 w-full">
            {/* Transitions */}
            <SectionLabel>Transitions</SectionLabel>
            <div className="grid grid-cols-3 gap-1.5 w-full">
                {TRANSITION_LIST.map(eff => (
                    <EffectPreview key={eff.id} effect={eff.id} text={config.content} fontFamily={config.fontFamily}
                        isSelected={config.effect === eff.id} onClick={() => handleEffectClick(eff.id)} />
                ))}
            </div>

            {/* Kinetic */}
            <SectionLabel>Kinetic</SectionLabel>
            <div className="grid grid-cols-3 gap-1.5 w-full">
                {KINETIC_LIST.map(eff => (
                    <EffectPreview key={eff.id} effect={eff.id} text={config.content} fontFamily={config.fontFamily}
                        isSelected={config.effect === eff.id} onClick={() => handleEffectClick(eff.id)} />
                ))}
            </div>

            {/* Controls */}
            {showControls && (
                <div className="space-y-2.5 pt-1">
                    {/* Granularity */}
                    <div className="flex flex-col gap-1.5 w-full">
                        <span className="text-[11px] font-medium text-[rgba(255,255,255,0.35)] px-1 tracking-[0.1px]">Apply By</span>
                        <SegmentedToggle
                            items={[{ value: 'char', label: 'Char' }, { value: 'word', label: 'Word' }, { value: 'line', label: 'Line' }]}
                            value={config.granularity}
                            onChange={(val) => onUpdate({ granularity: val as AnimationGranularity })}
                        />
                    </div>

                    {/* Smoothing — all effects except typewriter and none */}
                    {showEasing && (
                        <div className="flex flex-col gap-1.5 pt-2 w-full">
                            <span className="text-[11px] font-medium text-[rgba(255,255,255,0.35)] px-1 tracking-[0.1px]">Smoothing</span>
                            <SegmentedToggle
                                items={[{ value: 'linear', label: 'Linear' }, { value: 'smooth', label: 'Smooth' }]}
                                value={config.easing}
                                onChange={(val) => onUpdate({ easing: val as AnimationEasing })}
                            />
                        </div>
                    )}

                    {/* Speed — stack + kinetic (continuous) */}
                    {showSpeed && <div className="pt-2"><RangeSlider label="Speed" min={0.25} max={8} step={0.25} formatValue={v => `${v}×`} value={config.speed} onChange={(val) => onUpdate({ speed: val })} /></div>}

                    {/* Amplitude — wave, wiggle */}
                    {showAmplitude && <div className="pt-2"><RangeSlider label="Amplitude" min={5} max={200} step={5} formatValue={v => `${v}%`} value={config.intensity} onChange={(val) => onUpdate({ intensity: val })} /></div>}

                    {/* Stack transition */}
                    {isStack && (
                        <div className="flex flex-col gap-1.5 pt-2 w-full">
                            <span className="text-[11px] font-medium text-[rgba(255,255,255,0.35)] px-1 tracking-[0.1px]">Transition</span>
                            <SegmentedToggle
                                items={[{ value: 'blur', label: 'Blur' }, { value: 'cut', label: 'Cut' }, { value: 'fade', label: 'Fade' }]}
                                value={config.stackTransition || 'cut'}
                                onChange={(val) => onUpdate({ stackTransition: val as StackTransition })}
                            />
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

