import React, { useRef, useEffect, useState, useCallback } from 'react';
import { MediaAsset, TextConfig } from '../types';
import { AnimatedText } from './AnimatedText';
import { timeController } from '../services/TimeController';

interface StageProps {
    media: MediaAsset | null;
    configs: TextConfig[];
    selectedId: string | null;
    isPlaying: boolean;
    animationKey: number;
    onUpdatePosition: (pos: { x: number; y: number }) => void;
    onMetadataLoaded: (duration: number) => void;
    onSelectLayer: (id: string) => void;
    placeholderDuration?: number;
}

export const Stage: React.FC<StageProps> = ({
    media,
    configs,
    selectedId,
    isPlaying,
    animationKey,
    onUpdatePosition,
    onMetadataLoaded,
    onSelectLayer,
    placeholderDuration = 8
}) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const videoRef = useRef<HTMLVideoElement>(null);
    const [isDragging, setIsDragging] = useState(false);
    const [aspectRatio, setAspectRatio] = useState(1920 / 1080);
    const rafId = useRef<number>();
    const lastTime = useRef<number>(performance.now());
    const seekRafId = useRef<number>();

    const updateLoop = useCallback(() => {
        if (isPlaying) {
            const now = performance.now();
            const delta = (now - lastTime.current) / 1000;
            lastTime.current = now;

            if (videoRef.current) {
                timeController.setTime(videoRef.current.currentTime);
            } else {
                const nextTime = (timeController.getTime() + delta) % placeholderDuration;
                timeController.setTime(nextTime);
            }
            rafId.current = requestAnimationFrame(updateLoop);
        }
    }, [isPlaying, placeholderDuration]);

    useEffect(() => {
        lastTime.current = performance.now();
        if (isPlaying) {
            rafId.current = requestAnimationFrame(updateLoop);
        } else {
            if (rafId.current) cancelAnimationFrame(rafId.current);
        }
        return () => {
            if (rafId.current) cancelAnimationFrame(rafId.current);
        };
    }, [isPlaying, updateLoop]);

    useEffect(() => {
        if (!videoRef.current) return;
        if (isPlaying) videoRef.current.play().catch(() => { });
        else videoRef.current.pause();
    }, [isPlaying]);

    // High-performance scrubbing synchronization
    useEffect(() => {
        const unsubscribe = timeController.subscribe((time) => {
            if (!videoRef.current || isPlaying) return;
            // Abs precision seek for scrubbing
            videoRef.current.currentTime = time;
        });

        return unsubscribe;
    }, [isPlaying]);

    const handleMouseDown = (e: React.MouseEvent, id: string) => {
        e.stopPropagation();
        onSelectLayer(id);
        setIsDragging(true);
    };

    useEffect(() => {
        const handleMouseMove = (e: MouseEvent) => {
            if (!isDragging || !containerRef.current) return;
            const rect = containerRef.current.getBoundingClientRect();
            const x = ((e.clientX - rect.left) / rect.width) * 100;
            const y = ((e.clientY - rect.top) / rect.height) * 100;
            onUpdatePosition({
                x: Math.max(0, Math.min(100, x)),
                y: Math.max(0, Math.min(100, y))
            });
        };

        const handleMouseUp = () => setIsDragging(false);

        if (isDragging) {
            window.addEventListener('mousemove', handleMouseMove);
            window.addEventListener('mouseup', handleMouseUp);
        }
        return () => {
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mouseup', handleMouseUp);
        };
    }, [isDragging, onUpdatePosition]);




    const handleMediaLoad = (e: React.SyntheticEvent<HTMLVideoElement | HTMLImageElement>) => {
        const target = e.currentTarget;
        let w = 0, h = 0;
        if (target instanceof HTMLVideoElement) {
            w = target.videoWidth;
            h = target.videoHeight;
            onMetadataLoaded(target.duration);
        } else if (target instanceof HTMLImageElement) {
            w = target.naturalWidth;
            h = target.naturalHeight;
            // Keep default timeline duration for images (don't change it)
        }
        if (w && h) setAspectRatio(w / h);
    };

    const bgOpacity = configs.reduce((max, c) => Math.max(max, c.bgOpacity || 0), 0);

    return (
        <div
            ref={containerRef}
            className="relative shadow-2xl bg-black group overflow-hidden select-none border border-white/5 transition-all duration-500 ease-in-out rounded-xl"
            style={{
                aspectRatio: `${aspectRatio}`,
                ...(aspectRatio > 1
                    ? { width: '100%', maxWidth: '100%', maxHeight: '100%' }
                    : { height: '100%', maxHeight: '100%', maxWidth: '100%' }),
                flexShrink: 1,
                minWidth: 0,
                minHeight: 0
            }}
        >
            {/* Background Media */}
            {!media ? (
                <div className="w-full h-full bg-gradient-to-br from-zinc-800 to-zinc-950" />
            ) : media.type === 'video' ? (
                <video
                    ref={videoRef}
                    src={media.dataUrl}
                    className="w-full h-full object-contain pointer-events-none opacity-80"
                    muted loop playsInline
                    onLoadedMetadata={handleMediaLoad}
                />
            ) : (
                <img
                    src={media.dataUrl}
                    className="w-full h-full object-contain pointer-events-none opacity-80"
                    onLoad={handleMediaLoad}
                />
            )}

            {/* Overlays for DOM Capture */}
            <div id="stage-overlays" className="absolute inset-0 z-10 pointer-events-none">
                {/* Dim Overlay */}
                <div
                    className="absolute inset-0 bg-black pointer-events-none"
                    style={{ opacity: bgOpacity / 100 }}
                />

                {/* Text Layers */}
                {configs.map(config => {
                    // Note: We MUST keep elements mounted so AnimeJS doesn't lose ref topology
                    // Visibility logic is pushed to AnimatedText via opacity handling.
                    return (
                        <AnimatedText
                            key={config.id}
                            config={config}
                            isPlaying={isPlaying}
                            animationKey={animationKey}
                            selectedId={selectedId}
                            onSelectLayer={handleMouseDown}
                        />
                    );
                })}
            </div>
        </div>
    );
};

import React, { useRef, useEffect, useCallback, memo } from 'react';
import { timeController } from '../services/TimeController';
import { TextConfig } from '../types';
import { Icon } from './Icon';

interface TimelineProps {
    duration: number;
    configs: TextConfig[];
    selectedId: string | null;
    isPlaying: boolean;
    onPlayPause: () => void;
    onRestart: () => void;
    onSeek: (time: number) => void;
    onUpdateConfig: (updates: Partial<TextConfig>, id: string) => void;
    onBatchUpdate: (updates: Array<{ id: string; changes: Partial<TextConfig> }>) => void;
    onSelectLayer: (id: string) => void;
}

/** Minimum block duration in ms — blocks will not shrink below this */
const MIN_BLOCK_MS = 300;

/* ─── Drag state: entirely in refs for zero re-renders ─── */

interface DragState {
    mode: 'move' | 'resize-start' | 'resize-end';
    activeId: string;
    startX: number;
    startDelay: number;
    startDuration: number;
    currentDelay: number;
    currentDuration: number;
}

export const Timeline: React.FC<TimelineProps> = memo(({
    duration, configs, selectedId, isPlaying,
    onPlayPause, onRestart, onSeek, onUpdateConfig, onBatchUpdate, onSelectLayer
}) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const blockRefs = useRef<Map<string, HTMLDivElement>>(new Map());
    const dragRef = useRef<DragState | null>(null);

    const timeTextRef = useRef<HTMLSpanElement>(null);
    const playheadRef = useRef<HTMLDivElement>(null);

    // Keep latest props in refs for closure-free access
    const durationRef = useRef(duration);
    durationRef.current = duration;
    const configsRef = useRef(configs);
    configsRef.current = configs;
    const onSeekRef = useRef(onSeek);
    onSeekRef.current = onSeek;
    const onSelectLayerRef = useRef(onSelectLayer);
    onSelectLayerRef.current = onSelectLayer;
    const onBatchUpdateRef = useRef(onBatchUpdate);
    onBatchUpdateRef.current = onBatchUpdate;

    /* ─── Playhead subscription ─── */
    useEffect(() => {
        const unsubscribe = timeController.subscribe((time) => {
            if (timeTextRef.current) timeTextRef.current.innerText = formatTime(time);
            if (durationRef.current > 0 && playheadRef.current) {
                playheadRef.current.style.left = `${(time / durationRef.current) * 100}%`;
            }
        });
        return unsubscribe;
    }, []);

    const getTimeFromX = useCallback((clientX: number) => {
        if (!containerRef.current || durationRef.current === 0) return 0;
        const rect = containerRef.current.getBoundingClientRect();
        const padding = 4;
        const width = rect.width - padding * 2;
        const x = clientX - rect.left - padding;
        return Math.max(0, Math.min(1, x / width)) * durationRef.current;
    }, []);

    /* ─── Seek (scrub playhead on track background) ─── */
    const handleTrackMouseDown = useCallback((e: React.MouseEvent) => {
        if ((e.target as HTMLElement).closest('[data-block-id]')) return;
        onSeekRef.current(getTimeFromX(e.clientX));
        const onMove = (ev: MouseEvent) => onSeekRef.current(getTimeFromX(ev.clientX));
        const onUp = () => {
            window.removeEventListener('mousemove', onMove);
            window.removeEventListener('mouseup', onUp);
        };
        window.addEventListener('mousemove', onMove);
        window.addEventListener('mouseup', onUp);
    }, [getTimeFromX]);

    /* ─── Block drag: only the dragged block moves during drag ─── */
    const startDrag = useCallback((e: React.MouseEvent, id: string, mode: 'move' | 'resize-start' | 'resize-end') => {
        e.stopPropagation();
        e.preventDefault();
        onSelectLayerRef.current(id);

        const currentConfigs = configsRef.current;
        const config = currentConfigs.find(c => c.id === id);
        if (!config || !containerRef.current) return;

        // Jump playhead for move clicks
        if (mode === 'move') {
            const visibleTime = (config.delay + config.inDuration + 100) / 1000;
            const endTime = (config.delay + config.duration) / 1000;
            onSeekRef.current(Math.min(visibleTime, endTime, durationRef.current));
        }

        dragRef.current = {
            mode,
            activeId: id,
            startX: e.clientX,
            startDelay: config.delay,
            startDuration: config.duration,
            currentDelay: config.delay,
            currentDuration: config.duration,
        };

        // Dragged block: no transition, elevated z-index, slightly transparent
        const draggedEl = blockRefs.current.get(id);
        if (draggedEl) {
            draggedEl.style.transition = 'none';
            draggedEl.style.zIndex = '25';
            draggedEl.style.opacity = '0.85';
        }

        document.body.style.cursor = mode === 'move' ? 'grabbing' : 'ew-resize';

        const onMove = (ev: MouseEvent) => {
            const drag = dragRef.current;
            if (!drag || !containerRef.current) return;

            const rect = containerRef.current.getBoundingClientRect();
            const deltaX = ev.clientX - drag.startX;
            const deltaTimeMs = (deltaX / rect.width) * durationRef.current * 1000;
            const totalMs = durationRef.current * 1000;
            const dur = durationRef.current;

            let newDelay = drag.startDelay;
            let newDuration = drag.startDuration;

            if (drag.mode === 'move') {
                newDelay = Math.max(0, Math.min(totalMs - drag.startDuration, drag.startDelay + deltaTimeMs));
                newDuration = drag.startDuration;
            } else if (drag.mode === 'resize-start') {
                const rawDelay = drag.startDelay + deltaTimeMs;
                const maxDelay = (drag.startDelay + drag.startDuration) - MIN_BLOCK_MS;
                newDelay = Math.max(0, Math.min(maxDelay, rawDelay));
                newDuration = (drag.startDelay + drag.startDuration) - newDelay;
            } else {
                // resize-end
                const rawEnd = (drag.startDelay + drag.startDuration) + deltaTimeMs;
                newDuration = Math.max(MIN_BLOCK_MS, Math.min(totalMs - drag.startDelay, rawEnd - drag.startDelay));
                newDelay = drag.startDelay;
            }

            // Update ONLY the dragged block's DOM — everything else stays put
            const el = blockRefs.current.get(drag.activeId);
            if (el) {
                el.style.left = `${(newDelay / 1000 / dur) * 100}%`;
                el.style.width = `${(newDuration / 1000 / dur) * 100}%`;
            }

            drag.currentDelay = newDelay;
            drag.currentDuration = newDuration;
        };

        const onUp = () => {
            const drag = dragRef.current;

            if (drag) {
                const dur = durationRef.current;

                // Reset all block styles
                blockRefs.current.forEach((el) => {
                    el.style.transition = 'left 150ms ease-out, width 150ms ease-out, opacity 150ms ease-out';
                    el.style.opacity = '';
                    el.style.zIndex = '';
                });

                // Animate dragged block to final position
                const el = blockRefs.current.get(drag.activeId);
                if (el) {
                    el.style.left = `${(drag.currentDelay / 1000 / dur) * 100}%`;
                    el.style.width = `${(drag.currentDuration / 1000 / dur) * 100}%`;
                }

                // After animation, commit to React state
                setTimeout(() => {
                    blockRefs.current.forEach((el) => {
                        el.style.transition = '';
                    });

                    const updates = [{
                        id: drag.activeId,
                        changes: { delay: drag.currentDelay, duration: drag.currentDuration } as Partial<TextConfig>,
                    }];
                    onBatchUpdateRef.current(updates);
                }, 160);
            }

            document.body.style.cursor = '';
            dragRef.current = null;

            window.removeEventListener('mousemove', onMove);
            window.removeEventListener('mouseup', onUp);
        };

        window.addEventListener('mousemove', onMove);
        window.addEventListener('mouseup', onUp);
    }, []);

    /* ─── Block ref callback ─── */
    const setBlockRef = useCallback((id: string) => (el: HTMLDivElement | null) => {
        if (el) blockRefs.current.set(id, el);
        else blockRefs.current.delete(id);
    }, []);

    if (duration === 0) return null;

    return (
        <div className="w-full space-y-2 select-none flex flex-col">
            {/* Controls */}
            <div className="flex items-center justify-between px-1">
                <div className="flex items-center gap-3">
                    <div className="flex items-center gap-1">
                        <button onClick={onPlayPause}
                            className="w-[34px] h-[34px] flex items-center justify-center rounded-xl hover:bg-white/5 active:bg-white/10 transition-colors text-white">
                            <Icon name={isPlaying ? 'pause' : 'play_arrow'} size={18} filled />
                        </button>
                        <button onClick={onRestart}
                            className="w-[34px] h-[34px] flex items-center justify-center rounded-xl hover:bg-white/5 active:bg-white/10 transition-colors text-white">
                            <Icon name="replay" size={16} />
                        </button>
                    </div>
                    <span ref={timeTextRef} style={{ fontFamily: 'Google Sans Flex' }} className="text-[12px] font-medium tracking-[0.1px] text-[rgba(255,255,255,0.35)] tabular-nums">
                        {formatTime(timeController.getTime())}
                    </span>
                </div>
                <span style={{ fontFamily: 'Google Sans Flex' }} className="text-[12px] font-medium tracking-[0.1px] text-[rgba(255,255,255,0.35)] tabular-nums">
                    {formatTime(duration)}
                </span>
            </div>

            {/* Hit area wrapper — extends above the visible track for easier scrubbing */}
            <div
                ref={containerRef}
                onMouseDown={handleTrackMouseDown}
                className="relative w-full cursor-pointer"
                style={{ paddingTop: '12px', marginTop: '-12px' }}
            >
                {/* Visible track — same height as before */}
                <div className="relative h-[48px] w-full bg-transparent rounded-xl border border-[#595959] p-1">
                <div className="absolute inset-x-1 inset-y-0">
                    {configs.map((config, idx) => {
                        const startPercent = ((config.delay || 0) / 1000 / duration) * 100;
                        const widthPercent = ((config.duration || 0) / 1000 / duration) * 100;
                        const isSelected = selectedId === config.id;
                        const inW = (config.inDuration / config.duration) * 100;
                        const outW = (config.outDuration / config.duration) * 100;

                        return (
                            <div
                                key={config.id}
                                ref={setBlockRef(config.id)}
                                data-block-id={config.id}
                                onMouseDown={(e) => startDrag(e, config.id, 'move')}
                                className={`absolute top-1 bottom-1 rounded-lg z-10 cursor-grab active:cursor-grabbing border overflow-hidden group/clip will-change-[left,width] transition-colors\n                                    ${isSelected
                                        ? 'bg-[#969696] border-[#969696] z-20'
                                        : 'bg-transparent border-[#595959] hover:bg-white/5 hover:border-[#7a7a7a]'
                                    }`}
                                style={{ left: `${startPercent}%`, width: `${widthPercent}%`, opacity: 0.75 }}
                            >
                                {/* In/Out fade zones */}
                                <div className={`absolute left-0 top-0 bottom-0 pointer-events-none rounded-l-md ${isSelected ? 'bg-black/10' : 'bg-white/5'}`} style={{ width: `${inW}%` }} />
                                <div className={`absolute right-0 top-0 bottom-0 pointer-events-none rounded-r-md ${isSelected ? 'bg-black/10' : 'bg-white/5'}`} style={{ width: `${outW}%` }} />

                                {/* Resize handles */}
                                <div onMouseDown={(e) => startDrag(e, config.id, 'resize-start')}
                                    className="absolute left-0 top-0 bottom-0 w-2 cursor-ew-resize hover:bg-white/20 z-30 transition-colors" />
                                <div onMouseDown={(e) => startDrag(e, config.id, 'resize-end')}
                                    className="absolute right-0 top-0 bottom-0 w-2 cursor-ew-resize hover:bg-white/20 z-30 transition-colors" />

                                {/* Label */}
                                <div className="absolute inset-0 flex items-center px-3 pointer-events-none overflow-hidden">
                                    <span style={{ fontFamily: 'Google Sans Flex' }} className={`text-[12px] font-medium tracking-[0.1px] whitespace-nowrap truncate ${isSelected ? 'text-black' : 'text-white'}`}>
                                        {config.content || `Layer ${idx + 1}`}
                                    </span>
                                </div>
                            </div>
                        );
                    })}

                    {/* Playhead */}
                    <div
                        ref={playheadRef}
                        className="absolute top-0 bottom-0 w-px bg-white/80 z-40 pointer-events-none"
                        style={{ left: `${(timeController.getTime() / duration) * 100}%` }}
                    >
                        <div className="absolute -top-1 left-1/2 -translate-x-1/2 w-3.5 h-3.5 bg-white rounded-full shadow-[0_0_8px_rgba(255,255,255,0.4)]" />
                    </div>
                </div>
                </div>
            </div>
        </div>
    );
});

function formatTime(seconds: number) {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    const ms = Math.floor((seconds % 1) * 100);
    return `${mins}:${secs.toString().padStart(2, '0')}.${ms.toString().padStart(2, '0')}`;
}

import { Input, Output, Conversion, Mp4OutputFormat, BufferTarget, BlobSource, ALL_FORMATS } from "mediabunny";
import { Flow } from "flow-sdk";
import { toCanvas } from "html-to-image";
import { timeController } from "./TimeController";
import { MediaAsset, TextConfig } from "../types";

/**
 * Convert ArrayBuffer to base64 in chunks to avoid stack overflow and
 * string size limits that cause corrupt payloads for large videos.
 */
function arrayBufferToBase64(buffer: ArrayBuffer): string {
  const bytes = new Uint8Array(buffer);
  const chunkSize = 32768;
  const parts: string[] = [];
  for (let i = 0; i < bytes.length; i += chunkSize) {
    const chunk = bytes.subarray(i, Math.min(i + chunkSize, bytes.length));
    parts.push(String.fromCharCode.apply(null, chunk as unknown as number[]));
  }
  return btoa(parts.join(''));
}

/**
 * Wait for the browser to fully flush DOM updates.
 * Double-rAF ensures React has committed and the compositor has painted.
 */
function doubleRAF(): Promise<void> {
  return new Promise(resolve =>
    requestAnimationFrame(() => requestAnimationFrame(() => resolve()))
  );
}

/** Single rAF — used in render loop where speed matters more. */
function singleRAF(): Promise<void> {
  return new Promise(resolve => requestAnimationFrame(resolve));
}

/**
 * Style properties whitelist for html-to-image.
 * Only these CSS properties are cloned per node, avoiding ~300+ default copies.
 */
const STYLE_WHITELIST = [
  'font-family', 'font-size', 'font-weight', 'font-style',
  'letter-spacing', 'line-height', 'text-align', 'white-space',
  'color', 'text-decoration', 'text-transform',
  'display', 'position', 'top', 'left', 'right', 'bottom',
  'width', 'height', 'min-width', 'min-height', 'max-width', 'max-height',
  'margin', 'padding', 'box-sizing', 'overflow',
  'opacity', 'visibility', 'background', 'background-color',
  'border', 'border-radius', 'box-shadow',
  'transform', 'transform-origin',
  'flex', 'flex-direction', 'align-items', 'justify-content', 'gap',
  'z-index', 'pointer-events',
];

/** Filter out display:none nodes to speed up html-to-image cloning.
 *  Note: we intentionally keep opacity:0 nodes because they still occupy
 *  layout space — removing them shifts text alignment (e.g. right-aligned). */
function visibleFilter(node: HTMLElement): boolean {
  if (node.nodeType !== 1) return true;
  const s = node.style;
  if (s && s.display === 'none') return false;
  return true;
}

/**
 * Get the stage overlay element used for DOM capture.
 */
function getOverlayElement(): HTMLElement | null {
  return document.getElementById("stage-overlays");
}

/**
 * Check if any layer has animated content (effect !== 'none').
 */
function hasAnimatedContent(configs: TextConfig[]): boolean {
  return configs.some(c => c.effect !== 'none');
}

/**
 * Manually fetch Google Fonts CSS and inline the font files as base64.
 * This bypasses the CORS cssRules issue entirely by fetching the raw CSS
 * ourselves and converting woff2 URLs to data URIs.
 */
async function fetchGoogleFontCSS(): Promise<string> {
  const links = Array.from(document.querySelectorAll('link[rel="stylesheet"]'))
    .filter(el => (el as HTMLLinkElement).href?.includes('fonts.googleapis.com'));

  if (links.length === 0) return '';

  const cssChunks: string[] = [];

  for (const link of links) {
    try {
      const res = await fetch((link as HTMLLinkElement).href, {
        headers: { 'Accept': 'text/css' }
      });
      const css = await res.text();

      const urlRegex = new RegExp('url\\((https?:\\/\\/[^)]+)\\)', 'g');
      let inlined = css;
      const matches = [...css.matchAll(urlRegex)];

      for (const match of matches) {
        try {
          const fontRes = await fetch(match[1]);
          const fontBuf = await fontRes.arrayBuffer();
          const b64 = arrayBufferToBase64(fontBuf);
          const mime = match[1].includes('.woff2') ? 'font/woff2'
            : match[1].includes('.woff') ? 'font/woff'
              : 'font/truetype';
          inlined = inlined.replace(match[0], 'url(data:' + mime + ';base64,' + b64 + ')');
        } catch {
          // ignore
        }
      }

      cssChunks.push(inlined);
    } catch {
      // ignore
    }
  }

  return cssChunks.join(String.fromCharCode(10));
}

/**
 * Capture the stage overlays DOM as a canvas image.
 * pixelRatio controls render quality — higher = crisper text at large resolutions.
 */
async function captureOverlay(
  overlayEl: HTMLElement,
  fontCSS: string,
  pixelRatio: number
): Promise<HTMLCanvasElement> {
  return toCanvas(overlayEl, {
    fontEmbedCSS: fontCSS || undefined,
    width: overlayEl.offsetWidth,
    height: overlayEl.offsetHeight,
    pixelRatio,
    skipAutoScale: true,
    includeStyleProperties: STYLE_WHITELIST,
    preferredFontFormat: 'woff2',
    filter: visibleFilter,
  });
}

/**
 * Generate a silent WebM video from a still image canvas at the given FPS and duration.
 * Uses captureStream(0) + requestFrame() to force frame emission on a static canvas.
 * The canvas must be continuously redrawn to ensure captureStream actually produces frames,
 * because browsers skip frame generation when canvas content hasn't changed.
 */
async function generateStillVideo(
  bgCanvas: HTMLCanvasElement,
  durationSec: number,
  fps: number = 24
): Promise<Blob> {
  const ctx = bgCanvas.getContext('2d')!;
  // Snapshot the canvas content so we can redraw it to force frame emission
  const imageData = ctx.getImageData(0, 0, bgCanvas.width, bgCanvas.height);

  const stream = bgCanvas.captureStream(0); // 0 = manual frame control
  const videoTrack = stream.getVideoTracks()[0] as any;

  const mediaRecorder = new MediaRecorder(stream, {
    mimeType: 'video/webm;codecs=vp9',
    videoBitsPerSecond: 8_000_000,
  });

  const chunks: Blob[] = [];
  mediaRecorder.ondataavailable = (e) => {
    if (e.data.size > 0) chunks.push(e.data);
  };

  return new Promise((resolve, reject) => {
    let redrawInterval: ReturnType<typeof setInterval>;

    mediaRecorder.onstop = () => {
      clearInterval(redrawInterval);
      const blob = new Blob(chunks, { type: 'video/webm' });
      resolve(blob);
    };
    mediaRecorder.onerror = reject;
    mediaRecorder.start();

    // Continuously redraw the canvas + request frames at the target FPS.
    // This runs in real-time so the MediaRecorder timestamps are correct.
    redrawInterval = setInterval(() => {
      ctx.putImageData(imageData, 0, 0);
      if (videoTrack.requestFrame) videoTrack.requestFrame();
    }, 1000 / fps);

    setTimeout(() => {
      mediaRecorder.stop();
      stream.getTracks().forEach(t => t.stop());
    }, durationSec * 1000);
  });
}

// ─── VIDEO EXPORT ───────────────────────────────────────────

export async function renderVideo(
  media: MediaAsset | null,
  configs: TextConfig[],
  onProgress: (p: number) => void,
  signal?: AbortSignal,
  totalDuration: number = 8
) {
  // Smart export: only export as image if the source is an image AND no animated content
  if (media && media.type === "image" && !hasAnimatedContent(configs)) {
    return await renderImageOverlay(media, configs);
  }

  // Ensure all Google Fonts are loaded before capture
  await document.fonts.ready;

  const overlayEl = getOverlayElement();
  if (!overlayEl) throw new Error("Stage overlay element not found");

  // Pre-compute font embed CSS — manual fetch bypasses CORS cssRules error
  const fontCSS = await fetchGoogleFontCSS();

  let sourceBlob: Blob;
  let outputWidth = 1920;
  let outputHeight = 1080;
  let isPortrait = false;

  if (media && media.type === 'video') {
    // Video background — use the source video directly
    const response = await fetch(media.dataUrl);
    sourceBlob = await response.blob();

    // Detect source dimensions for correct aspect ratio
    const sourceVideo = document.querySelector('video[src]') as HTMLVideoElement | null;
    const srcW = sourceVideo?.videoWidth || 1280;
    const srcH = sourceVideo?.videoHeight || 720;
    isPortrait = srcH > srcW;
    outputWidth = srcW;
    outputHeight = srcH;
  } else {
    // Image background or no background — generate a still video at 24fps
    const bgCanvas = document.createElement('canvas');

    if (media && media.type === 'image') {
      // Draw the image as a still background
      const img = new Image();
      img.src = media.dataUrl;
      await img.decode();
      bgCanvas.width = img.width;
      bgCanvas.height = img.height;
      outputWidth = img.width;
      outputHeight = img.height;
      isPortrait = img.height > img.width;
      const ctx = bgCanvas.getContext('2d')!;
      ctx.drawImage(img, 0, 0);
    } else {
      // No background — use a gradient matching the placeholder
      bgCanvas.width = 1920;
      bgCanvas.height = 1080;
      const ctx = bgCanvas.getContext('2d')!;
      const gradient = ctx.createLinearGradient(0, 0, bgCanvas.width, bgCanvas.height);
      gradient.addColorStop(0, '#27272a'); // zinc-800
      gradient.addColorStop(1, '#09090b'); // zinc-950
      ctx.fillStyle = gradient;
      ctx.fillRect(0, 0, bgCanvas.width, bgCanvas.height);
    }

    onProgress(0.02);
    // Generate at 1fps to minimize real-time frame callbacks (8 frames vs 192 at 24fps)
    sourceBlob = await generateStillVideo(bgCanvas, totalDuration, 1);
    onProgress(0.05);
  }

  const input = new Input({ source: new BlobSource(sourceBlob), formats: ALL_FORMATS });
  const output = new Output({
    format: new Mp4OutputFormat({ fastStart: "in-memory" }),
    target: new BufferTarget()
  });

  // Lock TimeController so Stage playback loop can't interfere
  timeController.isLocked = true;

  let renderCanvas: HTMLCanvasElement | null = null;
  let renderCtx: CanvasRenderingContext2D | null = null;
  let overlayPixelRatio = 1;

  try {
    const conversion = await Conversion.init({
      input,
      output,
      video: {
        forceTranscode: true,
        frameRate: 24,
        // Set the longer edge to 1080 for crisp output regardless of orientation
        ...(isPortrait ? { width: 1080 } : { height: 1080 }),
        fit: 'contain',
        bitrate: 8_000_000,
        process: async (sample: any) => {
          if (signal?.aborted) {
            throw new Error("Render cancelled");
          }
          const w = sample.displayWidth;
          const h = sample.displayHeight;

          if (!renderCanvas) {
            renderCanvas = document.createElement('canvas');
            renderCanvas.width = w;
            renderCanvas.height = h;
            renderCtx = renderCanvas.getContext('2d')!;

            // Cap pixel ratio at 2 for video export
            const previewH = overlayEl.offsetHeight || 540;
            overlayPixelRatio = Math.min(2, Math.max(1, Math.ceil(h / previewH)));
          }

          // 1. Draw the source video frame (mediabunny upscales for us)
          sample.draw(renderCtx!, 0, 0);

          // 2. Seek our animation system to this frame's time
          timeController.forceSetTime(sample.timestamp);

          // 3. Wait for DOM to flush (React + anime.js transforms)
          await singleRAF();

          // 4. Capture the DOM overlay at high resolution
          try {
            const overlayCanvas = await captureOverlay(overlayEl, fontCSS, overlayPixelRatio);

            // 5. Composite overlay onto video frame
            renderCtx!.drawImage(overlayCanvas, 0, 0, w, h);
          } catch (captureErr) {
            // If capture fails for a single frame, skip overlay (don't crash the export)
            console.warn('Overlay capture failed for frame at', sample.timestamp, captureErr);
          }

          return renderCanvas;
        }
      }
    });

    if (!conversion.isValid) throw new Error("Invalid conversion");
    conversion.onProgress = onProgress;
    await conversion.execute();

    // Create result as blob URL
    const buffer = output.target.buffer;
    const videoBlob = new Blob([buffer], { type: "video/mp4" });
    const dataUrl = URL.createObjectURL(videoBlob);
    const mimeType = "video/mp4";

    // Save via Flow SDK (needs base64 for the API)
    const base64 = arrayBufferToBase64(buffer);
    const flowResult = await Flow.save({
      base64,
      mimeType,
      name: `TextOverlays_${Date.now()}.mp4`
    });

    return { flowResult, dataUrl, mimeType };
  } finally {
    // Always unlock TimeController
    timeController.isLocked = false;
  }
}

// ─── IMAGE EXPORT ───────────────────────────────────────────

export async function renderImageOverlay(media: MediaAsset, configs?: TextConfig[]) {
  await document.fonts.ready;

  const overlayEl = getOverlayElement();

  const img = new Image();
  img.src = media.dataUrl;
  await img.decode();

  const canvas = document.createElement("canvas");
  canvas.width = img.width;
  canvas.height = img.height;
  const ctx = canvas.getContext("2d")!;

  // Draw base image
  ctx.drawImage(img, 0, 0);

  // Composite text overlays at time 0
  if (overlayEl && configs && configs.length > 0) {
    const fontCSS = await fetchGoogleFontCSS();
    const previewH = overlayEl.offsetHeight || 540;
    const pixelRatio = Math.max(1, Math.ceil(img.height / previewH));

    // Seek to time 0 and capture
    timeController.isLocked = true;
    timeController.forceSetTime(0);
    await doubleRAF();

    try {
      const overlayCanvas = await captureOverlay(overlayEl, fontCSS, pixelRatio);
      ctx.drawImage(overlayCanvas, 0, 0, img.width, img.height);
    } catch (captureErr) {
      console.warn('Overlay capture failed for image export', captureErr);
    } finally {
      timeController.isLocked = false;
    }
  }

  const dataUrl = canvas.toDataURL("image/png");
  const mimeType = "image/png";

  // Auto-save via Flow SDK
  let flowResult;
  try {
    const base64 = dataUrl.split(',')[1];
    flowResult = await Flow.save({ base64, mimeType, name: `TextOverlays_${Date.now()}.png` });
  } catch { }

  return { flowResult, dataUrl, mimeType };
}

type Listener = (time: number) => void;

class TimeController {
    private time: number = 0;
    private listeners: Set<Listener> = new Set();
    public isLocked: boolean = false;

    setTime(t: number) {
        if (this.isLocked) return;
        this.time = t;
        this.notify();
    }

    forceSetTime(t: number) {
        this.time = t;
        this.notify();
    }

    getTime() {
        return this.time;
    }

    subscribe(listener: Listener) {
        this.listeners.add(listener);
        return () => {
            this.listeners.delete(listener);
        };
    }

    private notify() {
        this.listeners.forEach(l => l(this.time));
    }
}

export const timeController = new TimeController();

export interface MediaAsset {
    type: 'video' | 'image';
    dataUrl: string;
    mimeType?: string;
}

export type AnimationEffect =
    | 'none'
    | 'sequential-stack'
    | 'blur-in'
    | 'typewriter'
    | 'slide-up'
    | 'slide-fade'
    | 'wave'
    | 'wiggle'
    | 'font-shuffle';

export type AnimationGranularity = 'char' | 'word' | 'line';
export type AnimationEasing = 'linear' | 'smooth';
export type StackTransition = 'blur' | 'cut' | 'fade';

export const KINETIC_EFFECTS = new Set<AnimationEffect>(['wave', 'wiggle', 'font-shuffle']);
export const TRANSITION_EFFECTS = new Set<AnimationEffect>(['blur-in', 'typewriter', 'slide-up', 'slide-fade']);
export const EFFECTS_WITH_SPEED = new Set<AnimationEffect>(['sequential-stack', 'wave', 'wiggle', 'font-shuffle']);
export const EFFECTS_WITH_AMPLITUDE = new Set<AnimationEffect>(['wave', 'wiggle']);
export const EFFECTS_WITH_EASING = new Set<AnimationEffect>(['blur-in', 'slide-up', 'slide-fade', 'sequential-stack', 'wave', 'wiggle', 'font-shuffle']);

export interface TextConfig {
    id: string;
    content: string;
    fontFamily: string;
    fontSize: number;
    fontWeight: number;
    letterSpacing: number;
    lineHeight: number;
    textAlign: 'left' | 'center' | 'right';
    color: string;
    backgroundColor: string;
    bgOpacity: number;
    position: { x: number; y: number };
    effect: AnimationEffect;
    granularity: AnimationGranularity;
    easing: AnimationEasing;
    speed: number; // 0.25 – 4, multiplier on animation speed (1 = default)
    stackTransition: StackTransition; // How sequential-stack items transition
    duration: number; // Total Lifespan on timeline (ms)
    delay: number;    // Start Time on timeline (ms)
    inDuration: number;  // Entrance Animation length (ms)
    outDuration: number; // Exit Animation length (ms)
    intensity: number;   // 0-200, kinetic effect strength (wave/wiggle amplitude)
}

